    defragged_task{evidence_sha256:"50f0cdb5a20416fec6712dcf7ec9d0656ecd36161232565bec7708284a0ae51f", status:already_complete, blocker:none, complete_statement:"1. Head outside. Make sure that it is a sunny day and you take a measuring device (like a tape measure or meter stick) as well as a pencil and some paper. 2. Choose an object whose height is too large to measure directly. Your teacher may assign you an object. 3. Use what you have learned to figure out the height of the object. Explain or show your reasoning.", statement_joiner:" ", statement_segments:[seg_84d563ec05ea6c457d12, seg_c1af1210e5f2dcd4747e, seg_eec14e48cbd5d15ea7b5], source_statement:"1. Head outside. Make sure that it is a sunny day and you take a measuring device (like a tape measure or meter stick) as well as a pencil and some paper. 2. Choose an object whose height is too large to measure directly. Your teacher may assign you an object. 3. Use what you have learned to figure out the height of the object. Explain or show your reasoning.", source_statement_joiner:" ", source_statement_segments:[seg_84d563ec05ea6c457d12, seg_c1af1210e5f2dcd4747e, seg_eec14e48cbd5d15ea7b5], statement_repair_class:complete_source, referents:[], visuals:[], source_segments:[segment{id:"seg_84d563ec05ea6c457d12", path:"curriculum/im_teacher_guides_docling/Grade8/Grade8-2-13-Lesson-teacher-guide-/document.md", line_start:449, line_end:449, byte_start:37404, byte_end:37558, decoder:utf8, sha256:"76936ec3ce51e4420da909b58a1c2d05e381b501ea51778b6909fa497f608f9a"}, segment{id:"seg_c1af1210e5f2dcd4747e", path:"curriculum/im_teacher_guides_docling/Grade8/Grade8-2-13-Lesson-teacher-guide-/document.md", line_start:450, line_end:450, byte_start:37559, byte_end:37664, decoder:utf8, sha256:"ec545fabf41f633a3c21ed6b4ab8e9833c812eb27ec96b4b53ea732ecc7c180e"}, segment{id:"seg_eec14e48cbd5d15ea7b5", path:"curriculum/im_teacher_guides_docling/Grade8/Grade8-2-13-Lesson-teacher-guide-/document.md", line_start:451, line_end:451, byte_start:37665, byte_end:37765, decoder:utf8, sha256:"01944dc94085062905c0ce9ee605b21d26add245c75118e2d226b94956521b2c"}], source_evidence:task_evidence(rule(docling_task_heading_exact_copy),source('hermes/app/runtime/experiments/gemma4_tutor/docling/full-output/TeacherLessonGuides/Grade8/Grade8-2-13-Lesson-teacher-guide-/document.md',lines(449,451)),position(student_task_statement(4)),excerpt("1. Head outside. Make sure that it is a sunny day and you take a measuring device (like a tape measure or meter stick) as well as a pencil and some paper. 2. Choose an object whose height is too large to measure directly. Your teacher may assign you an object. 3. Use what you have learned to figure out the height of the object. Explain or show your reasoning."),extraction_status(complete),blocker(none),visual_provenance([]))}).

defragged_task_instance(im_defrag_3155de54f43b4280921bf13d_1,
    'IM-G8-U3-L1',
