    defragged_task{evidence_sha256:"ee836f506735ad88f33684cfeeaecb639d3055dffe9529e89511c8337c983cdc", status:already_complete, blocker:none, complete_statement:"Lin has a summer reading assignment. After reading the first 30 pages of the book, she plans to read 40 pages each day until she finishes. Lin makes the graph shown here to track how many total pages she'll read over the next few days. After day 1, Lin reaches page 70, which matches the point she made on her graph. After day 4, Lin reaches page 190, which does not match the point she made on her graph. Lin is not sure what went wrong since she knows she followed her reading plan. Why doesn't Lin's reading progress match her graph?", statement_joiner:" ", statement_segments:[seg_c1af617037fb9f674cf0, seg_8b61a9c6ef13b366a4a8], source_statement:"Lin has a summer reading assignment. After reading the first 30 pages of the book, she plans to read 40 pages each day until she finishes. Lin makes the graph shown here to track how many total pages she'll read over the next few days. After day 1, Lin reaches page 70, which matches the point she made on her graph. After day 4, Lin reaches page 190, which does not match the point she made on her graph. Lin is not sure what went wrong since she knows she followed her reading plan. Why doesn't Lin's reading progress match her graph?", source_statement_joiner:" ", source_statement_segments:[seg_c1af617037fb9f674cf0, seg_8b61a9c6ef13b366a4a8], statement_repair_class:complete_source, referents:[referent{surface:"the graph", kind:graph, status:missing, segments:[seg_1c1e8e51375a179d1135], antecedent:"", antecedent_segments:[], absence_reason:antecedent_not_in_available_source}], visuals:[], source_segments:[segment{id:"seg_c1af617037fb9f674cf0", path:"curriculum/im_teacher_guides_docling/Grade8/Grade8-3-6-Lesson-teacher-guide-/document.md", line_start:226, line_end:226, byte_start:15398, byte_end:15633, decoder:utf8, sha256:"b942436ce228fd04b90c066e438ef1d2fc487f507d6d71064055840cc7256f6c"}, segment{id:"seg_8b61a9c6ef13b366a4a8", path:"curriculum/im_teacher_guides_docling/Grade8/Grade8-3-6-Lesson-teacher-guide-/document.md", line_start:228, line_end:228, byte_start:15635, byte_end:15935, decoder:utf8, sha256:"a0058e6638c587a616902e3b399356b39fb516f946d2949cdd850368c7dcbc3d"}, segment{id:"seg_1c1e8e51375a179d1135", path:"curriculum/im_teacher_guides_docling/Grade8/Grade8-3-6-Lesson-teacher-guide-/document.md", line_start:226, line_end:226, byte_start:15547, byte_end:15556, decoder:utf8, sha256:"16b9f2912007922fe48f5343d131850f01f2095edbc97bf38d36efc3178bafc2"}], source_evidence:task_evidence(rule(docling_task_heading_exact_copy),source('hermes/app/runtime/experiments/gemma4_tutor/docling/full-output/TeacherLessonGuides/Grade8/Grade8-3-6-Lesson-teacher-guide-/document.md',lines(226,228)),position(student_task_statement(2)),excerpt("Lin has a summer reading assignment. After reading the first 30 pages of the book, she plans to read 40 pages each day until she finishes. Lin makes the graph shown here to track how many total pages she'll read over the next few days. After day 1, Lin reaches page 70, which matches the point she made on her graph. After day 4, Lin reaches page 190, which does not match the point she made on her graph. Lin is not sure what went wrong since she knows she followed her reading plan. Why doesn't Lin's reading progress match her graph?"),extraction_status(complete),blocker(none),visual_provenance([]))}).

