defragged_task_instance(im_defrag_073c301e02bbccf3b5ec6c95_1,
    'IM-G8-U4-L15',
    curriculum_task(section(2)),
    defragged_task{evidence_sha256:"7aad98bd1f505d3fc9ad695db9e9878cf3952069007588a3991b6df990d292f2", status:blocked_layout, blocker:expression_missing_without_visual, complete_statement:"", statement_joiner:" ", statement_segments:[], source_statement:"Your teacher will give you either a problem card, or a data card. Do not show or read your card to your partner. If your teacher gives you the problem card: 1. Silently read your card and think about what information you need to answer the question. 2. Ask your partner for the specific information that you need. 'Can you tell me ?' 3. Explain to your partner how you are using the information to solve the problem. 'I need to know because . . . .' Continue to ask questions until you have enough 4. information to solve the problem. 4. When you have enough information, share the problem card with your partner, and solve the problem independently. 5. Read the data card, and discuss your reasoning.", source_statement_joiner:" ", source_statement_segments:[], statement_repair_class:complete_source, referents:[], visuals:[], source_segments:[segment{id:"seg_151ff0318754ea9b5db1", path:"curriculum/im/generated/grade_8_extracted_task_instances.pl", line_start:924, line_end:924, byte_start:529786, byte_end:530487, decoder:json_string_ascii, sha256:"0cfb56f7bdc327e682dc15c05818ab9a4f464eb4f26f7fd1ee7c4051fc978f95"}], available_fragment:"Your teacher will give you either a problem card, or a data card. Do not show or read your card to your partner. If your teacher gives you the problem card: 1. Silently read your card and think about what information you need to answer the question. 2. Ask your partner for the specific information that you need. 'Can you tell me ?' 3. Explain to your partner how you are using the information to solve the problem. 'I need to know because . . . .' Continue to ask questions until you have enough 4. information to solve the problem. 4. When you have enough information, share the problem card with your partner, and solve the problem independently. 5. Read the data card, and discuss your reasoning.", fragment_joiner:" ", fragment_segments:[seg_151ff0318754ea9b5db1], source_evidence:task_evidence(rule(docling_task_heading_exact_copy),source('hermes/app/runtime/experiments/gemma4_tutor/docling/full-output/TeacherLessonGuides/Grade8/Grade8-4-15-Lesson-teacher-guide-/document.md',lines(219,228)),position(student_task_statement(2)),excerpt("Your teacher will give you either a problem card, or a data card. Do not show or read your card to your partner. If your teacher gives you the problem card: 1. Silently read your card and think about what information you need to answer the question. 2. Ask your partner for the specific information that you need. 'Can you tell me ?' 3. Explain to your partner how you are using the information to solve the problem. 'I need to know because . . . .' Continue to ask questions until you have enough 4. information to solve the problem. 4. When you have enough information, share the problem card with your partner, and solve the problem independently. 5. Read the data card, and discuss your reasoning."),extraction_status(blocked_layout),blocker(expression_missing_without_visual),visual_provenance([]))}).

defragged_task_instance(im_defrag_4125e1f53b948b35764eccde_1,
    'IM-G8-U4-L15',
