    defragged_task{evidence_sha256:"75f7a43c1b72681b54e472c45124a201facf51f90c93b15e96f989d70e23de0e", status:already_complete, blocker:none, complete_statement:"A small company is selling a new board game, and they need to know how many to produce in the future. After 12 months, they sold 4 thousand games. After 18 months, they sold 7 thousand games. And after 36 months, they sold 15 thousand games. Could this information be reasonably estimated using a single linear model? If so, use the model to estimate the number of games sold after 48 months. If not, explain your reasoning.", statement_joiner:" ", statement_segments:[seg_bd3b32ca58e9a87ef084, seg_29a337d1b355704b8a0f, seg_c1e7dc374a251391cad8], source_statement:"A small company is selling a new board game, and they need to know how many to produce in the future. After 12 months, they sold 4 thousand games. After 18 months, they sold 7 thousand games. And after 36 months, they sold 15 thousand games. Could this information be reasonably estimated using a single linear model? If so, use the model to estimate the number of games sold after 48 months. If not, explain your reasoning.", source_statement_joiner:" ", source_statement_segments:[seg_bd3b32ca58e9a87ef084, seg_29a337d1b355704b8a0f, seg_c1e7dc374a251391cad8], statement_repair_class:complete_source, referents:[], visuals:[], source_segments:[segment{id:"seg_bd3b32ca58e9a87ef084", path:"curriculum/im_teacher_guides_docling/Grade8/Grade8-5-9-Lesson-teacher-guide-/document.md", line_start:498, line_end:498, byte_start:44345, byte_end:44446, decoder:utf8, sha256:"3b276d068a87356dd6d0ee3b2ce3f7b1a6b379128de403d1ef16bbacdcd65994"}, segment{id:"seg_29a337d1b355704b8a0f", path:"curriculum/im_teacher_guides_docling/Grade8/Grade8-5-9-Lesson-teacher-guide-/document.md", line_start:500, line_end:500, byte_start:44448, byte_end:44587, decoder:utf8, sha256:"a80042bbe68869ed368f4dca9351c15893697c8bd075a33cdf13bef85511a464"}, segment{id:"seg_c1e7dc374a251391cad8", path:"cu