),blocker(expression_missing_from_markdown),visual_provenance([visual_source(asset('hermes/app/runtime/experiments/gemma4_tutor/docling/full-output/TeacherLessonGuides/Grade8/Grade8-5-22-Lesson-teacher-guide-/document_artifacts/image_000041_1343712face9dcd2a48a5de75e7433b543c79c53f57e439e8d8d8de401662e7f.png'),description_file('hermes/app/runtime/experiments/gemma4_tutor/docling/full-output/TeacherLessonGuides/Grade8/Grade8-5-22-Lesson-teacher-guide-/picture_descriptions.md'),model('ibm-granite/granite-vision-3.3-2b (auto_inline)')),visual_source(asset('hermes/app/runtime/experiments/gemma4_tutor/docling/full-output/TeacherLessonGuides/Grade8/Grade8-5-22-Lesson-teacher-guide-/document_artifacts/image_000042_9af6b852abd406dc34e8c13fb977aca0e6cde31cbef174534d189bde25bda51c.png'),description_file('hermes/app/runtime/experiments/gemma4_tutor/docling/full-output/TeacherLessonGuides/Grade8/Grade8-5-22-Lesson-teacher-guide-/picture_descriptions.md'),model('ibm-granite/granite-vision-3.3-2b (auto_inline)')),visual_source(asset('hermes/app/runtime/experiments/gemma4_tutor/docling/full-output/TeacherLessonGuides/Grade8/Grade8-5-22-Lesson-teacher-guide-/document_artifacts/image_000043_2ecbb1b0192f28696342c2b0c812cf2370b5495d7eabf9bbab9f47dc306b6129.png'),description_file('hermes/app/runtime/experiments/gemma4_tutor/docling/full-output/TeacherLessonGuides/Grade8/Grade8-5-22-Lesson-teacher-guide-/picture_descriptions.md'),model('ibm-granite/granite-vision-3.3-2b (auto_inline)')),visual_source(asset('hermes/app/runtime/experiments/gemma4_tutor/docling/full-output/TeacherLessonGuides/Grade8/Grade8-5-22-Lesson-teacher-guide-/document_artifacts/image_000044_f3fc67b6eab4a10f635bba3be0197c1d57f8799dcb98b2c1d1a0bbbe61eea9b9.png'),description_file('hermes/app/runtime/experiments/gemma4_tutor/docling/full-output/TeacherLessonGuides/Grade8/Grade8-5-22-Lesson-teacher-guide-/picture_descriptions.md'),model('ibm-granite/granite-vision-3.3-2b (auto_inline)')),visual_source(asset('hermes/app/r