    defragged_task{evidence_sha256:"fdb720180cab62931f691d33f54722840db89a9120a1dea02d764c51ea5332be", status:blocked_layout, blocker:expression_missing_without_visual, complete_statement:"", statement_joiner:" ", statement_segments:[], source_statement:"Your teacher will give you a set of cards. Each card contains a representation of some data. 1. Sort the systems into groups that represent the same situation. Be prepared to explain how you know where each representation belongs. 2. One of the groups does not have a two-way table . Make a two-way table for the situation described by the graphs in the group. 3. Label the bar graphs and segmented bar graphs so that the categories represented by each bar are indicated. 4. Describe in your own words the kind of information shown by a segmented bar graph.", source_statement_joiner:" ", source_statement_segments:[], statement_repair_class:complete_source, referents:[], visuals:[], source_segments:[segment{id:"seg_07c6ee89bcbff1112bc4", path:"curriculum/im/generated/grade_8_extracted_task_instances.pl", line_start:1456, line_end:1456, byte_start:822264, byte_end:822821, decoder:json_string_ascii, sha256:"1218ae73868164e03cfca73426f1f0d822ee265c87d0519b07fcb7a7ca413d1f"}], available_fragment:"Your teacher will give you a set of cards. Each card contains a representation of some data. 1. Sort the systems into groups that represent the same situation. Be prepared to explain how you know where each representation belongs. 2. One of the groups does not have a two-way table . Make a two-way table for the situation described by the graphs in the group. 3. Label the bar graphs and segmented bar graphs so that the categories represented by each bar are indicated. 4. Describe in your own words the kind of information shown by a segmented bar graph.", fragment_joiner:" ", fragment_segments:[seg_07c6ee89bcbff1112bc4], source_evidence:task_evidence(rule(docling_task_heading_exact_copy),source('hermes/app/runtime/experiments/gemma4_tutor/docling/full-output/TeacherLessonGuides/Grade8/Grade8-6-9-Lesson-teacher-guide-/document.md',lines(263,268)),position(student_task_statement(2)),excerpt("Your teacher will give you a set of cards. Each card contains a representation of some data. 1. Sort the systems into groups that represent the same situation. Be prepared to explain how you know where each representation belongs. 2. One of the groups does not have a two-way table . Make a two-way table for the situation described by the graphs in the group. 3. Label the bar graphs and segmented bar graphs so that the categories represented by each bar are indicated. 4. Describe in your own words the kind of information shown by a segmented bar graph."),extraction_status(blocked_layout),blocker(expression_missing_without_visual),visual_provenance([]))}).

defragged_task_instance(im_defrag_d783ef5968accc485335e5bb_1,
