    defragged_task{evidence_sha256:"0cd5c58edd77c873f3b12011b2a370a3db826c55b390e5408ec65fff47177c9c", status:already_complete, blocker:none, complete_statement:"1. What is the measure of each angle in an equilateral triangle? How do you know? 2. How many triangles can you fit together at 1 vertex? Explain why there is no space between the triangles. 3. Explain why you can continue the pattern of triangles to tessellate the plane. 4. How can you use your triangular tessellation of the plane to show that regular hexagons can be used to give a regular tessellation of the plane?", statement_joiner:" ", statement_segments:[seg_21a41e83027fb3cd83b4, seg_038813b88d64b4e386bd, seg_7d29ac712c272fdc3d1b, seg_f2a7add3f6953e333076], source_statement:"1. What is the measure of each angle in an equilateral triangle? How do you know? 2. How many triangles can you fit together at 1 vertex? Explain why there is no space between the triangles. 3. Explain why you can continue the pattern of triangles to tessellate the plane. 4. How can you use your triangular tessellation of the plane to show that regular hexagons can be used to give a regular tessellation of the plane?", source_statement_joiner:" ", source_statement_segments:[seg_21a41e83027fb3cd83b4, seg_038813b88d64b4e386bd, seg_7d29ac712c272fdc3d1b, seg_f2a7add3f6953e333076], statement_repair_class:complete_source, referents:[], visuals:[], source_segments:[segment{id:"seg_21a41e83027fb3cd83b4", path:"curriculum/im_teacher_guides_docling/Grade8/Grade8-9-2-Lesson-teacher-guide-/document.md", line_start:240, line_end:240, byte_start:19071, byte_end:19152, decoder:utf8, sha256:"f29ae5b34a8c043a23ebcf1041695cdf4a523386e8b030bf0059fea2e69c3e17"}, segment{id:"seg_038813b88d64b4e386bd", path:"curriculum/im_teacher_guides_docling/Grade8/Grade8-9-2-Lesson-teacher-guide-/document.md", line_start:241, line_end:241, byte_start:19153, byte_end:19261, decoder:utf8, sha256:"1adbd4fe430801e0b212b7d190dfd2a60ce8133717eb017af4f4fdfe29742aa9"}, segment{id:"seg_7d29ac712c272fdc3d1b", path:"curriculum/im_teacher_guides_docling/Grade8/Grade8-9-2-Lesson-teacher-guide-/document.md", line_start:242, line_end:242, byte_start:19262, byte_end:19343, decoder:utf8, sha256:"4d250a4275b3717f6e07daf9ddc8396a32ff4877f39f0122b0a083856b9491d1"}, segment{id:"seg_f2a7add3f6953e333076", path:"curriculum/im_teacher_guides_docling/Grade8/Grade8-9-2-Lesson-teacher-guide-/document.md", line_start:243, line_end:243, byte_start:19344, byte_end:19491, decoder:utf8, sha256:"796c55931749365ed5262f72a14ebf2391de8ce3a3185ec25ccab0503628a45a"}], source_evidence:task_evidence(rule(docling_task_heading_exact_copy),source('hermes/app/runtime/experiments/gemma4_tutor/docling/full-output/TeacherLessonGuides/Grade8/Grade8-9-2-Lesson-teacher-guide-/document.md',lines(240,243)),position(student_task_statement(2)),excerpt("1. What is the measure of each angle in an equilateral triangle? How do you know? 2. How many triangles can you fit together at 1 vertex? Explain why there is no space between the triangles. 3. Explain why you can continue the pattern of triangles to tessellate the plane. 4. How can you use your triangular tessellation of the plane to show that regular hexagons can be used to give a regular tessellation of the plane?"),extraction_status(complete),blocker(none),visual_provenance([]))}).

defragged_task_instance(im_defrag_051ee5df066e75d23420b95c_1,
    'IM-G8-U9-L2',
