    defragged_task{evidence_sha256:"64957105a30fda8de53ceb7785058c61cde5fb25816d544eb0424efdda4c35d9", status:already_complete, blocker:none, complete_statement:"Play Compare with 2 players. 1. Shuffle the cards and split the deck between the players. 2. Each player turns over a card. 3. Compare the values. The player with the greater value keeps both cards. 4. If the values are the same, each player turns over 1 more card. The player with the greater value keeps all 4 cards. 5. Play until you run out of cards. The player with the most cards at the end of the game wins.", statement_joiner:" ", statement_segments:[seg_e1fcea0c173c3428d924, seg_8c1e15d83f75e657b696, seg_9d563954b18f86f42776, seg_85c278f47a715abef84e, seg_55d49d256fbcddf1a849, seg_cb7ce2e2eb9e0d0149d3, seg_58b265a40dc5da060a26, seg_497ceda62e92a1301e75, seg_570536f1a3c8c7094f98, seg_a3518a747bd98b52f16c, seg_a6fba342664256d89481], source_statement:"Play Compare with 2 players. 1. Shuffle the cards and split the deck between the players. 2. Each player turns over a card. 3. Compare the values. The player with the greater value keeps both cards. 4. If the values are the same, each player turns over 1 more card. The player with the greater value keeps all 4 cards. 5. Play until you run out of cards. The player with the most cards at the end of the game wins.", source_statement_joiner:" ", source_statement_segments:[seg_e1fcea0c173c3428d924, seg_8c1e15d83f75e657b696, seg_9d563954b18f86f42776, seg_85c278f47a715abef84e, seg_55d49d256fbcddf1a849, seg_cb7ce2e2eb9e0d0149d3, seg_58b265a40dc5da060a26, seg_497ceda62e92a1301e75, seg_570536f1a3c8c7094f98, seg_a3518a747bd98b52f16c, seg_a6fba342664256d89481], statement_repair_class:complete_source, referents:[], visuals:[], source_segments:[segment{id:"seg_e1fcea0c173c3428d924", path:"curriculum/im_teacher_guides/grade3/unit4/lesson20.md", line_start:320, line_end:320, byte_start:18107, byte_end:18135, decoder:utf8, sha256:"db1941fded5e372a276afc570f7714427e99ff56f194