    defragged_task{evidence_sha256:"9c68372cbf89a62b33685aefdaa749053968f38fcf61cd7d26e4205e2bc00df0", status:already_complete, blocker:none, complete_statement:"Han has a rectangular piece of paper that is 96 inches by 36 inches. He is using it to create a banner for Awards Day. Last year the banner measured 2,304 square inches. 1. Will the new banner fit in the same area that the old banner was located? Explain or show your reasoning. 2. What is the difference in square inches between the area of last year\u2019s banner and this year\u2019s banner?", statement_joiner:" ", statement_segments:[seg_c445b13b54809bee38ea, seg_6f4f7dda5a8951827217, seg_34edeb560f640fc6413c, seg_0f897814207cedf93b89], source_statement:"Han has a rectangular piece of paper that is 96 inches by 36 inches. He is using it to create a banner for Awards Day. Last year the banner measured 2,304 square inches. 1. Will the new banner fit in the same area that the old banner was located? Explain or show your reasoning. 2. What is the difference in square inches between the area of last year\u2019s banner and this year\u2019s banner?", source_statement_joiner:" ", source_statement_segments:[seg_c445b13b54809bee38ea, seg_6f4f7dda5a8951827217, seg_34edeb560f640fc6413c, seg_0f897814207cedf93b89], statement_repair_class:complete_source, referents:[], visuals:[], source_segments:[segment{id:"seg_c445b13b54809bee38ea", path:"curriculum/im_teacher_guides/grade4/unit6/lesson23.md", line_start:361, line_end:361, byte_start:21125, byte_end:21238, decoder:utf8, sha256:"9ae99b88935c6ec9f368e19481ec34a5e387826e770901982ef41f2651a78077"}, segment{id:"seg_6f4f7dda5a8951827217", path:"curriculum/im_teacher_guides/grade4/unit6/lesson23.md", line_start:362, line_end:362, byte_start:21245, byte_end:21300, decoder:utf8, sha256:"047565293f52e94f94755f866e0eca3c03a1a36e46160292c3c2db5f9057e084"}, segment{id:"seg_34edeb560f640fc6413c", path:"curriculum/im_teacher_guides/grade4/unit6/lesson23.md", line_start:364, line_end