    defragged_task{evidence_sha256:"4211a7956a73da3eb79ff8636d22e7944bd5ae1d21d674c2c20a30496417a1e2", status:already_complete, blocker:none, complete_statement:"Work with a partner in this activity. Choose a role: A or B. Sit back to back, or use a divider to keep one partner from seeing the other partner\u2019s work. Partner A: \u2022 Your teacher will give you a card. Don\u2019t show it to your partner. \u2022 Describe both images on the card\u2014as clearly and precisely as possible\u2014so that your partner can draw the same images. Partner B: \u2022 Your partner will describe 2 images. Listen carefully to the descriptions. \u2022 Create the drawings as described. Follow the instructions as closely as possible. 1. Compare your drawings to the original images. Discuss: \u25e6 How are your drawings and the original images alike? How are they different? \u25e6 How would you improve the descriptions? 2. Switch roles. Repeat the directions with a new card. If you have time: Request two new cards from your teacher (one card at a time). Take turns describing and drawing the geometric figure on each card.", statement_joiner:" ", statement_segments:[seg_934afdb9fcfee9d219e0, seg_2381e83c39a41fdf20a2, seg_c236a8d0dfcc130f89a0, seg_80b4c6e5170f77db349b, seg_af6d6c730a109e5ba2f3, seg_fc916443497be82be6a4, seg_17bd9c8cef1c5f6fbdee, seg_601c36cac000377f9828, seg_89a069b4bffca9b0a454, seg_932d65707b058f485dfe, seg_70ffac2582fc089625be, seg_964d35d2a6a7bfc0ffe0, seg_f6d78faee39f757cf563, seg_0394340dcb91d51a3979, seg_91b973dcf5d50818c22b, seg_a6d35ab38e488cee7e33, seg_4a0bc9a5efb865f94bb9, seg_7c9b24e36f94039640ac, seg_58e562f2c1d0108d755c, seg_7e9278686c4e59c033e3, seg_45f926c36e0871401810, seg_01ff4e3ae7601d86fcf3, seg_a46fb20071afb5d9ba5b, seg_36b910cbc41eba5fa113], source_statement:"Work with a partner in this activity. Choose a role: A or B. Sit back to back, or use a divider to keep one partner from seeing the other partner\u2019s work. Partner A: \u2022 Your teacher will give you a card. Don\u2019t show it to your partner. \u2022 Describe both images on the card\u2014as clearly and precisely as possible\u2014so that your partner can draw the same images. Partner B: \u2022 Your partner will describe 2 images. Listen carefully to the descriptions. \u2022 Create the drawings as described. Follow the instructions as closely as possible. 1. Compare your drawings to the original images. Discuss: \u25e6 How are your drawings and the original images alike? How are they different? \u25e6 How would you improve the descriptions? 2. Switch roles. Repeat the directions with a new card. If you have time: Request two new cards from your teacher (one card at a time). Take turns describing and drawing the geometric figure on each card.", source_statement_joiner:" ", source_statement_segments:[seg_934afdb9fcfee9d219e0, seg_2381e83c39a41fdf20a2, seg_c236a8d0dfcc130f89a0, seg_80b4c6e5170f77db349b, seg_af6d6c730a109e5ba2f3, seg_fc916443497be82be6a4, seg_17bd9c8cef1c5f6fbdee, seg_601c36cac000377f9828, seg_89a069b4bffca9b0a454, seg_932d65707b058f485dfe, seg_70ffac2582fc089625be, seg_964d35d2a6a7bfc0ffe0, seg_f6d78faee39f757cf563, seg_0394340dcb91d51a3979, seg_91b973dcf5d50818c22b, seg_a6d35ab38e488cee7e33, seg_4a0bc9a5efb865f94bb9, seg_7c9b24e36f94039640ac, seg_58e562f2c1d0108d755c, seg_7e9278686c4e59c033e3, seg_45f926c36e0871401810, seg_01ff4e3ae7601d86fcf3, seg_a46fb20071afb5d9ba5b, seg_36b910cbc41eba5fa113], statement_repair_class:complete_source, referents:[], visuals:[], source_segments:[segment{id:"seg_934afdb9fcfee9d219e0", path:"curriculum/im_teacher_guides/grade4/unit7/lesson5.md", line_start:187, line_end:187, byte_start:9916, byte_end:9970, decoder:utf8, sha256:"955e25dd7aacf7f3bb04d929f6cd92dfb0a7af28344fabfc68650df654a5d8fd"}, segment{id:"seg_2381e83c39a41fdf20a2", path:"curriculum/im_teacher_guides/grade4/unit7/lesson5.md", line_start:188, line_end:188, byte_start:10000, byte_end:10052, decoder:utf8, sha256:"7fcf689930f2d0185866123fa990251